class UserService {
  constructor(private repo: UserRepository) {}
  getUser(id: string) { return this.repo.findById(id); }
  saveUser(u: User) { return this.repo.save(u); }
  deleteUser(id: string) { return this.repo.remove(id); }
}

class ReportService {
  constructor(private repo: ReportRepo) {}
  listReports(userId: string) { return this.repo.findByUser(userId); }
  getReport(id: string) { return this.repo.get(id); }
  saveReport(r: Report) { return this.repo.save(r); }
}

