class InvoiceService {
  constructor(private repo: InvoiceRepo) {}
  getInvoiceSummary(customerId: string) {
    const invoices = this.repo.findByCustomer(customerId);
    return invoices.map(i => summarizeInvoice(i));
  }
  saveInvoice(inv: Invoice) { return this.repo.save(inv); }
}
